<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// panel root groups → THREE.Group containers, shown/hidden/repositioned for tabbed or linked overview
// panel (a) surface plate → PlaneGeometry(3.2,2.0) in XZ plane, material switches black/white/transparent/yellow
// panel (a) gray footprint → Line loop on XZ plane just below plate
// panel (a) visible spectrum arrows → CylinderGeometry shafts + ConeGeometry heads, colored violet/blue/cyan/green/yellow/orange/red
// panel (a) absorbed markers → small crossed Line segments at impact points
// panel (a) reflected/transmitted arrows → arrow groups leaving plate, visibility controlled by surface type and selected wavelength
// panel (a) legend → miniature arrows and labels for absorbed/reflected/transmitted
// panel (b) color wheel → many ShapeGeometry wedge sectors in a camera-facing local plane
// panel (b) wedge boundaries and outline → black Line radial spokes and circular polyline
// panel (b) selected/complement markers → small colored rim spheres and pointer lines opposite on wheel
// panel (b) sector click targets → registered wedge meshes setting the wavelength slider
// panel (c) test tube glass → transparent CapsuleGeometry plus torus rim, pale cyan outlines/highlights
// panel (c) blue solution → cylinder/sphere/ellipse liquid column with dynamic apparent color
// panel (c) white-light and transmitted bundles → horizontal colored arrow groups, red/orange attenuated by absorption
// labels → addLabel CSS labels for panel titles, wavelength annotations, white-light text, and panel letters

const spectrum = [
  { name: 'violet', wl: 400, color: 0x4b00ff, css: '#4b00ff' },
  { name: 'blue', wl: 430, color: 0x1e3cff, css: '#1e3cff' },
  { name: 'cyan', wl: 490, color: 0x49e6e6, css: '#49e6e6' },
  { name: 'green', wl: 560, color: 0x33ff00, css: '#33ff00' },
  { name: 'yellow', wl: 580, color: 0xffe600, css: '#ffe600' },
  { name: 'orange', wl: 620, color: 0xff7a00, css: '#ff7a00' },
  { name: 'red', wl: 800, color: 0xff0000, css: '#ff0000' },
];

const state = {
  panelView: 'Color wheel (b)',
  wavelength: 620,
  surfaceType: 'Colored',
  step: 0
};

const root = new THREE.Group();
scene.add(root);

const panelA = new THREE.Group();
const panelB = new THREE.Group();
const panelC = new THREE.Group();
root.add(panelA, panelB, panelC);

const faceRight = new THREE.Vector3(Math.SQRT1_2, 0, -Math.SQRT1_2);
const faceUp = new THREE.Vector3(-0.408248290463863, 0.816496580927726, -0.408248290463863);
const faceNormal = new THREE.Vector3(0.577350269189626, 0.577350269189626, 0.577350269189626);
const faceMatrix = new THREE.Matrix4().makeBasis(faceRight, faceUp, faceNormal);
panelB.setRotationFromMatrix(faceMatrix);
panelC.setRotationFromMatrix(faceMatrix);

function makeMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: opacity >= 0.75
  });
}

function makeLine(points, color = 0x000000, opacity = 1) {
  const mat = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const geo = new THREE.BufferGeometry().setFromPoints(points);
  return new THREE.Line(geo, mat);
}

function orientBetween(obj, start, end) {
  const mid = start.clone().add(end).multiplyScalar(0.5);
  const dir = end.clone().sub(start);
  obj.position.copy(mid);
  obj.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
}

function makeArrow(start, end, color, radius = 0.022, headRadius = 0.085, headLength = 0.22, opacity = 1) {
  const g = new THREE.Group();
  const s = start.clone(), e = end.clone();
  const dir = e.clone().sub(s);
  const len = dir.length();
  const shaftEnd = s.clone().add(dir.clone().multiplyScalar(Math.max(0.01, (len - headLength) / len)));
  const mat = new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, Math.max(0.01, len - headLength), 12), mat);
  orientBetween(shaft, s, shaftEnd);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLength, 18), mat.clone());
  orientBetween(head, shaftEnd, e);
  g.add(shaft, head);
  g.userData.color = color;
  return g;
}

function setObjOpacity(obj, opacity) {
  obj.visible = opacity > 0.015;
  obj.traverse(o => {
    if (o.material) {
      o.material.transparent = opacity < 1;
      o.material.opacity = opacity;
      o.material.depthWrite = opacity >= 0.75;
    }
  });
}

function setMeshColor(obj, color) {
  obj.traverse(o => {
    if (o.material && o.material.color) o.material.color.set(color);
  });
}

function localWorld(group, x, y, z = 0) {
  return group.localToWorld(new THREE.Vector3(x, y, z));
}

function wavelengthToAngle(wl) {
  const a = [
    { wl: 400, deg: 165 },
    { wl: 430, deg: 210 },
    { wl: 490, deg: 270 },
    { wl: 560, deg: 330 },
    { wl: 580, deg: 390 },
    { wl: 620, deg: 450 },
    { wl: 800, deg: 525 },
  ];
  const w = Math.max(400, Math.min(800, wl));
  for (let i = 0; i < a.length - 1; i++) {
    if (w >= a[i].wl && w <= a[i + 1].wl) {
      const t = (w - a[i].wl) / (a[i + 1].wl - a[i].wl);
      return THREE.MathUtils.degToRad(a[i].deg + t * (a[i + 1].deg - a[i].deg));
    }
  }
  return THREE.MathUtils.degToRad(450);
}

function angleToWavelength(rad) {
  let deg = THREE.MathUtils.radToDeg(rad);
  while (deg < 165) deg += 360;
  while (deg > 525) deg -= 360;
  const a = [
    { wl: 400, deg: 165 },
    { wl: 430, deg: 210 },
    { wl: 490, deg: 270 },
    { wl: 560, deg: 330 },
    { wl: 580, deg: 390 },
    { wl: 620, deg: 450 },
    { wl: 800, deg: 525 },
  ];
  for (let i = 0; i < a.length - 1; i++) {
    if (deg >= a[i].deg && deg <= a[i + 1].deg) {
      const t = (deg - a[i].deg) / (a[i + 1].deg - a[i].deg);
      return Math.round((a[i].wl + t * (a[i + 1].wl - a[i].wl)) / 10) * 10;
    }
  }
  return 620;
}

function wavelengthColor(wl) {
  const colors = spectrum;
  let best = colors[0];
  for (const c of colors) if (Math.abs(c.wl - wl) < Math.abs(best.wl - wl)) best = c;
  return best.color;
}

function colorNameForWavelength(wl) {
  let best = spectrum[0];
  for (const c of spectrum) if (Math.abs(c.wl - wl) < Math.abs(best.wl - wl)) best = c;
  return best.name;
}

function complementaryName(wl) {
  const comp = angleToWavelength(wavelengthToAngle(wl) + Math.PI);
  return colorNameForWavelength(comp);
}

function spectralAbsorbFactor(wl, center) {
  const diff = Math.abs(wl - center);
  if (diff <= 35) return 1;
  if (diff <= 80) return 0.45;
  return 0;
}

/* Panel A */
const plateMat = makeMat(0xffff66, 0.92);
const plate = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 2.0), plateMat);
plate.rotation.x = -Math.PI / 2;
plate.position.set(0, 0, 0);
panelA.add(plate);

const fpY = -0.035;
const fp = [
  new THREE.Vector3(-1.6, fpY, -1.0), new THREE.Vector3(1.6, fpY, -1.0),
  new THREE.Vector3(1.6, fpY, 1.0), new THREE.Vector3(-1.6, fpY, 1.0),
  new THREE.Vector3(-1.6, fpY, -1.0)
];
const footprint = makeLine(fp, 0x808080, 1);
panelA.add(footprint);

const incomingA = [], reflectedA = [], transmittedA = [], markersA = [];
for (let i = 0; i < spectrum.length; i++) {
  const band = spectrum[i];
  const z = 0.78 - i * 0.26;
  const hit = new THREE.Vector3(-0.55 + i * 0.06, 0.08, z);
  const inc = makeArrow(new THREE.Vector3(-2.75, 1.05, z - 0.74), hit, band.color);
  panelA.add(inc);
  incomingA.push(inc);
  registerInteractive(inc, {
    title: `${band.name} light entering surface`,
    body: `This ${band.name} band is part of the incoming white-light spectrum. The material decides whether it is absorbed, reflected, or transmitted.`,
    tooltip: `${band.name} incoming band`
  });

  const refl = makeArrow(hit.clone().add(new THREE.Vector3(0, 0.03, 0)), new THREE.Vector3(1.75, 1.03, z + 0.55), band.color);
  panelA.add(refl);
  reflectedA.push(refl);
  registerInteractive(refl, {
    title: `${band.name} reflected light`,
    body: `Reflected ${band.name} wavelengths can reach an observer and contribute to the color seen from the surface.`,
    tooltip: `${band.name} reflected`
  });

  const trans = makeArrow(hit.clone().add(new THREE.Vector3(0, -0.02, 0)), new THREE.Vector3(1.75, -0.26, z + 0.45), band.color, 0.018, 0.075, 0.2, 0.55);
  panelA.add(trans);
  transmittedA.push(trans);
  registerInteractive(trans, {
    title: `${band.name} transmitted light`,
    body: `A transparent substance allows this band to continue through the plate instead of reflecting it from the surface.`,
    tooltip: `${band.name} transmitted`
  });

  const m1 = makeLine([new THREE.Vector3(hit.x - 0.08, hit.y + 0.03, hit.z - 0.08), new THREE.Vector3(hit.x + 0.08, hit.y + 0.03, hit.z + 0.08)], band.color, 1);
  const m2 = makeLine([new THREE.Vector3(hit.x - 0.08, hit.y + 0.03, hit.z + 0.08), new THREE.Vector3(hit.x + 0.08, hit.y + 0.03, hit.z - 0.08)], band.color, 1);
  const mg = new THREE.Group();
  mg.add(m1, m2);
  panelA.add(mg);
  markersA.push(mg);
}

const legendA = new THREE.Group();
legendA.position.set(-1.8, -0.05, 1.55);
legendA.add(makeArrow(new THREE.Vector3(0, 0.12, 0), new THREE.Vector3(0.45, 0.12, 0), 0x222222, 0.012, 0.045, 0.1));
legendA.add(makeArrow(new THREE.Vector3(0, -0.12, 0), new THREE.Vector3(0.45, -0.12, 0), 0xaaaaaa, 0.012, 0.045, 0.1, 0.55));
panelA.add(legendA);

/* Panel B */
const wheelR = 1.35;
const wheelGroup = new THREE.Group();
panelB.add(wheelGroup);
const wheelSegments = [];
const nWedges = 96;
for (let i = 0; i < nWedges; i++) {
  const a0 = THREE.MathUtils.degToRad(165 + i * 360 / nWedges);
  const a1 = THREE.MathUtils.degToRad(165 + (i + 1) * 360 / nWedges);
  const amid = (a0 + a1) / 2;
  const wl = angleToWavelength(amid);
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  const steps = 4;
  for (let k = 0; k <= steps; k++) {
    const a = a0 + (a1 - a0) * (k / steps);
    shape.lineTo(Math.cos(a) * wheelR, Math.sin(a) * wheelR);
  }
  shape.lineTo(0, 0);
  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(shape), makeMat(wavelengthColor(wl), 0.96));
  mesh.userData.wavelength = wl;
  wheelGroup.add(mesh);
  wheelSegments.push(mesh);
  registerInteractive(mesh, {
    title: `${wl} nm sector`,
    body: `Clicking this sector sets the absorbed wavelength. The opposite side of the wheel gives the complementary apparent color.`,
    tooltip: `Set absorbed wavelength near ${wl} nm`,
    onClick: () => {
      state.wavelength = wl;
      document.getElementById('wavelength').value = wl;
      updateAll(false);
    }
  });
}

const boundaryWaves = [400, 430, 490, 560, 580, 620, 800];
for (const wl of boundaryWaves) {
  const a = wavelengthToAngle(wl);
  wheelGroup.add(makeLine([new THREE.Vector3(0, 0, 0.012), new THREE.Vector3(Math.cos(a) * wheelR, Math.sin(a) * wheelR, 0.012)], 0x000000, 1));
}
const circlePts = [];
for (let i = 0; i <= 160; i++) {
  const a = i / 160 * Math.PI * 2;
  circlePts.push(new THREE.Vector3(Math.cos(a) * wheelR, Math.sin(a) * wheelR, 0.018));
}
wheelGroup.add(makeLine(circlePts, 0x000000, 1));

const selectedMarker = new THREE.Mesh(new THREE.SphereGeometry(0.075, 18, 12), makeMat(0xffffff, 1));
const compMarker = new THREE.Mesh(new THREE.SphereGeometry(0.065, 18, 12), makeMat(0xffffff, 1));
wheelGroup.add(selectedMarker, compMarker);

const selectedPointer = makeLine([new THREE.Vector3(), new THREE.Vector3(1, 0, 0)], 0x000000, 1);
const compPointer = makeLine([new THREE.Vector3(), new THREE.Vector3(-1, 0, 0)], 0x444444, 1);
wheelGroup.add(selectedPointer, compPointer);

let highlightArc = makeLine([new THREE.Vector3()], 0x000000, 1);
wheelGroup.add(highlightArc);

/* Panel C */
const tubeGroup = new THREE.Group();
panelC.add(tubeGroup);
const glassMat = makeMat(0xb7d9d9, 0.35);
const tubeGlass = new THREE.Mesh(new THREE.CapsuleGeometry(0.38, 2.35, 18, 32), glassMat);
tubeGlass.position.set(0, -0.05, 0.04);
tubeGroup.add(tubeGlass);
const rim = new THREE.Mesh(new THREE.TorusGeometry(0.38, 0.045, 10, 48), makeMat(0x88b6b6, 0.55));
rim.scale.y = 0.28;
rim.position.set(0, 1.35, 0.08);
tubeGroup.add(rim);
const rim2 = new THREE.Mesh(new THREE.TorusGeometry(0.27, 0.025, 8, 40), makeMat(0xdff7f7, 0.45));
rim2.scale.y = 0.25;
rim2.position.set(0, 1.37, 0.1);
tubeGroup.add(rim2);

const liqMat = makeMat(0x3f86ff, 0.76);
const liquidBody = new THREE.Mesh(new THREE.CylinderGeometry(0.30, 0.30, 1.88, 36), liqMat);
liquidBody.position.set(0, -0.35, 0.1);
tubeGroup.add(liquidBody);
const liquidBottom = new THREE.Mesh(new THREE.SphereGeometry(0.30, 36, 16), liqMat.clone());
liquidBottom.scale.y = 0.75;
liquidBottom.position.set(0, -1.29, 0.1);
tubeGroup.add(liquidBottom);
const liquidTop = new THREE.Mesh(new THREE.CircleGeometry(0.30, 40), liqMat.clone());
liquidTop.scale.y = 0.22;
liquidTop.position.set(0, 0.60, 0.12);
tubeGroup.add(liquidTop);

const highlight1 = makeLine([new THREE.Vector3(-0.18, 1.2, 0.16), new THREE.Vector3(-0.18, -1.28, 0.16)], 0xffffff, 0.55);
const highlight2 = makeLine([new THREE.Vector3(0.20, 1.05, 0.16), new THREE.Vector3(0.20, -1.12, 0.16)], 0xffffff, 0.28);
tubeGroup.add(highlight1, highlight2);

const incomingC = [], outgoingC = [], absorbedC = [];
for (let i = 0; i < spectrum.length; i++) {
  const band = spectrum[i];
  const y = 0.85 - i * 0.28;
  const inc = makeArrow(new THREE.Vector3(-2.85, y, 0), new THREE.Vector3(-0.55, y, 0), band.color, 0.014, 0.065, 0.16);
  panelC.add(inc);
  incomingC.push(inc);
  registerInteractive(inc, {
    title: `${band.name} component of white light`,
    body: `White light contains this ${band.name} component before it reaches the blue solution.`,
    tooltip: `${band.name} incoming light`
  });

  const out = makeArrow(new THREE.Vector3(0.65, y, 0), new THREE.Vector3(3.0, y, 0), band.color, 0.014, 0.065, 0.16);
  panelC.add(out);
  outgoingC.push(out);
  registerInteractive(out, {
    title: `${band.name} transmitted component`,
    body: `If not absorbed strongly by the solution, this component remains in the transmitted mixture seen by the eye.`,
