/* Updates */
function updateSurfacePanel() {
  const type = state.surfaceType;
  if (type === 'Black absorbing') {
    plateMat.color.set(0x000000);
    plateMat.opacity = 1; plateMat.transparent = false;
  } else if (type === 'White reflecting') {
    plateMat.color.set(0xf5f5f5);
    plateMat.opacity = 1; plateMat.transparent = false;
  } else if (type === 'Transparent') {
    plateMat.color.set(0xf8ffff);
    plateMat.opacity = 0.25; plateMat.transparent = true;
  } else {
    plateMat.color.set(0xffff66);
    plateMat.opacity = 0.92; plateMat.transparent = true;
  }

  for (let i = 0; i < spectrum.length; i++) {
    const band = spectrum[i];
    const selected = Math.abs(band.wl - state.wavelength) <= 35;
    const yellowish = band.name === 'yellow' || band.name === 'orange' || band.name === 'green';
    let reflect = false, transmit = false, absorb = false;

    if (type === 'Black absorbing') absorb = true;
    else if (type === 'White reflecting') reflect = true;
    else if (type === 'Transparent') transmit = true;
    else {
      reflect = yellowish && !selected;
      absorb = !reflect;
    }

    setObjOpacity(reflectedA[i], reflect ? (selected ? 1 : 0.9) : 0);
    setObjOpacity(transmittedA[i], transmit ? 0.65 : 0);
    setObjOpacity(markersA[i], absorb ? (selected ? 1 : 0.45) : 0);
    setObjOpacity(incomingA[i], selected ? 1 : 0.72);
    const scale = selected ? 1.18 : 1;
    incomingA[i].scale.setScalar(scale);
    reflectedA[i].scale.setScalar(selected ? 1.12 : 1);
  }
}

