userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Panel view
  <select id="panelView">
    <option>Surface interactions (a)</option>
    <option selected>Color wheel (b)</option>
    <option>Test tube (c)</option>
    <option>Linked overview</option>
  </select>
</label>
<label>Absorbed wavelength: <span id="wavelengthReadout">620 nm</span>
  <input id="wavelength" type="range" min="400" max="800" step="10" value="620">
</label>
<label>Surface type
  <select id="surfaceType">
    <option>Black absorbing</option>
    <option>White reflecting</option>
    <option>Transparent</option>
    <option selected>Colored</option>
  </select>
</label>
<div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:4px">
  <button id="prevStep">◀ Step</button>
  <button id="nextStep">Step ▶</button>
</div>
<div id="stepTitle" style="font-weight:bold;margin-top:4px">Absorption on the wheel</div>
<div id="stepNarration" style="line-height:1.3">Start on the color wheel with absorption near 620 nm, in the orange-red region. The marker opposite it indicates the complementary blue/cyan appearance.</div>
<div id="colorNote" style="line-height:1.3;margin-top:4px"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// panel containers → THREE.Group for (a), (b), (c), attached/removed to create fixed textbook panel views
// panel (a) four surface plates → PlaneGeometry rectangles in XZ plane arranged 2×2: black, outline/white reflecting, yellow reflecting, yellow complementary absorption
// panel (a) gray footprints → Line loops slightly below each plate
// panel (a) incoming visible-spectrum arrows → CylinderGeometry shafts + ConeGeometry heads, seven parallel colored arrows into each mini-plate
// panel (a) reflected arrows → matching colored arrows leaving upper-right/back-right for reflecting cases
// panel (a) transmitted arrows → faint continuation arrows through the transparent/outline case
// panel (a) absorbed markers → small colored stop disks/crosses at impact points for absorbed wavelengths
// panel (a) active surface highlight → black rectangular outline around selected surface-type quadrant
// panel (b) color wheel sectors → ShapeGeometry wedge meshes in camera-facing plane with black radial boundaries
// panel (b) selected/complement pointers → Line objects and rim SphereGeometry markers at opposite wheel positions
// panel (b) click highlight ring → short outer arc following selected wavelength
// panel (c) glass test tube → transparent CapsuleGeometry body plus TorusGeometry elliptical rim and pale outline
// panel (c) blue liquid → CylinderGeometry plus SphereGeometry rounded bottom and top ellipse
// panel (c) light bundles → seven incoming arrows, transmitted arrows with red/orange removed for 620 nm blue-appearing solution
// labels → addLabel for wavelength labels, panel letters, White light, Blue-appearing light, and compact annotation

const spectrum = [
  { name: 'violet', wl: 400, color: 0x4b00ff, css: '#4b00ff' },
  { name: 'blue', wl: 430, color: 0x1e3cff, css: '#1e3cff' },
  { name: 'cyan', wl: 490, color: 0x49e6e6, css: '#49e6e6' },
  { name: 'green', wl: 560, color: 0x33ff00, css: '#33ff00' },
  { name: 'yellow', wl: 580, color: 0xffe600, css: '#ffe600' },
  { name: 'orange', wl: 620, color: 0xff7a00, css: '#ff7a00' },
  { name: 'red', wl: 800, color: 0xff0000, css: '#ff0000' }
];

const wheelAnchors = [
  { wl: 400, deg: 180 },
  { wl: 430, deg: 210 },
  { wl: 490, deg: 270 },
  { wl: 560, deg: 330 },
  { wl: 580, deg: 390 },
  { wl: 620, deg: 450 },
  { wl: 800, deg: 510 }
];

const state = {
  panelView: 'Color wheel (b)',
  wavelength: 620,
  surfaceType: 'Colored',
  step: 0
};

const root = new THREE.Group();
scene.add(root);

const panelA = new THREE.Group();
const panelB = new THREE.Group();
const panelC = new THREE.Group();

const screenRight = new THREE.Vector3(Math.SQRT1_2, 0, -Math.SQRT1_2);
const screenUp = new THREE.Vector3(-0.408248290463863, 0.816496580927726, -0.408248290463863);
const screenNormal = new THREE.Vector3(0.577350269189626, 0.577350269189626, 0.577350269189626);
const faceMatrix = new THREE.Matrix4().makeBasis(screenRight, screenUp, screenNormal);
panelB.setRotationFromMatrix(faceMatrix);
panelC.setRotationFromMatrix(faceMatrix);

function mat(color, opacity = 1, side = THREE.DoubleSide) {
  return new THREE.MeshBasicMaterial({
    color,
    side,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 0.8
  });
}

function lineObj(points, color = 0x000000, opacity = 1) {
  return new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(points),
    new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity })
  );
}

function orientBetween(obj, start, end) {
  const dir = end.clone().sub(start);
  obj.position.copy(start).add(end).multiplyScalar(0.5);
  obj.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
}

function makeArrow(start, end, color, radius = 0.015, headRadius = 0.06, headLength = 0.16, opacity = 1) {
  const g = new THREE.Group();
  const s = start.clone();
  const e = end.clone();
  const dir = e.clone().sub(s);
  const len = Math.max(dir.length(), 0.001);
  const shaftLen = Math.max(0.01, len - headLength);
  const shaftEnd = s.clone().add(dir.clone().multiplyScalar(shaftLen / len));
  const m = mat(color, opacity, THREE.FrontSide);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, shaftLen, 10), m);
  orientBetween(shaft, s, shaftEnd);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLength, 16), m.clone());
  orientBetween(head, shaftEnd, e);
  g.add(shaft, head);
  return g;
}

function setOpacity(obj, opacity) {
  obj.visible = opacity > 0.01;
  obj.traverse(o => {
    if (o.material) {
      o.material.transparent = opacity < 1;
      o.material.opacity = opacity;
      o.material.depthWrite = opacity >= 0.8;
    }
  });
}

function setColor(obj, color) {
  obj.traverse(o => {
    if (o.material && o.material.color) o.material.color.set(color);
  });
}

function setLineGeometry(line, pts) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
}

function wlToAngle(wl) {
  const w = Math.max(400, Math.min(800, wl));
  for (let i = 0; i < wheelAnchors.length - 1; i++) {
    const a = wheelAnchors[i], b = wheelAnchors[i + 1];
    if (w >= a.wl && w <= b.wl) {
      const t = (w - a.wl) / (b.wl - a.wl);
      return THREE.MathUtils.degToRad(a.deg + t * (b.deg - a.deg));
    }
  }
  return THREE.MathUtils.degToRad(450);
}

function angleToWl(rad) {
  let deg = THREE.MathUtils.radToDeg(rad);
  while (deg < 180) deg += 360;
  while (deg > 540) deg -= 360;
  for (let i = 0; i < wheelAnchors.length - 1; i++) {
    const a = wheelAnchors[i], b = wheelAnchors[i + 1];
    if (deg >= a.deg && deg <= b.deg) {
      const t = (deg - a.deg) / (b.deg - a.deg);
      return Math.round((a.wl + t * (b.wl - a.wl)) / 10) * 10;
    }
  }
  return 620;
}

function nearestBand(wl) {
  let best = spectrum[0];
  for (const s of spectrum) {
    if (Math.abs(s.wl - wl) < Math.abs(best.wl - wl)) best = s;
  }
  return best;
}

function wavelengthColor(wl) {
  return nearestBand(wl).color;
}

function colorName(wl) {
  return nearestBand(wl).name;
}

function complementaryWavelength(wl) {
  return angleToWl(wlToAngle(wl) + Math.PI);
}

function complementaryName(wl) {
  return colorName(complementaryWavelength(wl));
}

function localToWorld(group, x, y, z = 0) {
  group.updateMatrixWorld(true);
  return group.localToWorld(new THREE.Vector3(x, y, z));
}

/* Panel (a): four fixed textbook surface cases */
const panelAMinis = [];
const activeFrames = {};

function plateFootprint(w = 1.55, h = 0.95, y = -0.018) {
  const pts = [
    new THREE.Vector3(-w / 2, y, -h / 2),
    new THREE.Vector3(w / 2, y, -h / 2),
    new THREE.Vector3(w / 2, y, h / 2),
    new THREE.Vector3(-w / 2, y, h / 2),
    new THREE.Vector3(-w / 2, y, -h / 2)
  ];
  return lineObj(pts, 0x808080, 1);
}

function makeAbsorbMark(pos, color) {
  const g = new THREE.Group();
  g.add(lineObj([
    new THREE.Vector3(pos.x - 0.045, pos.y + 0.025, pos.z - 0.045),
    new THREE.Vector3(pos.x + 0.045, pos.y + 0.025, pos.z + 0.045)
  ], color, 1));
  g.add(lineObj([
    new THREE.Vector3(pos.x - 0.045, pos.y + 0.025, pos.z + 0.045),
    new THREE.Vector3(pos.x + 0.045, pos.y + 0.025, pos.z - 0.045)
  ], color, 1));
  return g;
}

function makeMiniSurface(kind, pos) {
  const g = new THREE.Group();
  g.position.copy(pos);
  panelA.add(g);

  let pColor = 0xffff66, pOpacity = 0.92;
  if (kind === 'black') { pColor = 0x000000; pOpacity = 1; }
  if (kind === 'white') { pColor = 0xf8f8f8; pOpacity = 0.14; }
  if (kind === 'yellowReflect') { pColor = 0xffff66; pOpacity = 0.82; }
  if (kind === 'yellowAbsorb') { pColor = 0xffff66; pOpacity = 0.82; }

  const plate = new THREE.Mesh(new THREE.PlaneGeometry(1.55, 0.95), mat(pColor, pOpacity));
  plate.rotation.x = -Math.PI / 2;
  plate.position.y = 0;
  g.add(plate);
  g.add(plateFootprint());

  const inc = [], refl = [], trans = [], marks = [];
  for (let i = 0; i < spectrum.length; i++) {
    const band = spectrum[i];
    const z = 0.38 - i * 0.12;
    const hit = new THREE.Vector3(-0.33 + i * 0.035, 0.045, z);
    const start = hit.clone().add(new THREE.Vector3(-0.95, 0.58, -0.46));
    const incoming = makeArrow(start, hit, band.color, 0.0095, 0.045, 0.12, 1);
    g.add(incoming);
    inc.push(incoming);

    const out = makeArrow(hit.clone().add(new THREE.Vector3(0.02, 0.03, 0.015)), hit.clone().add(new THREE.Vector3(0.95, 0.48, 0.48)), band.color, 0.0095, 0.045, 0.12, 0.95);
    g.add(out);
    refl.push(out);

    const through = makeArrow(hit.clone().add(new THREE.Vector3(0.025, -0.015, 0.01)), hit.clone().add(new THREE.Vector3(0.95, -0.18, 0.43)), band.color, 0.008, 0.038, 0.105, 0.48);
    g.add(through);
    trans.push(through);

    const mark = makeAbsorbMark(hit, band.color);
    g.add(mark);
    marks.push(mark);

    registerInteractive(incoming, {
      title: `${band.name} incoming light`,
      body: `This is one component of the visible spectrum striking the surface.`,
      tooltip: `${band.name} incoming`
    });
  }

  const frame = lineObj([
    new THREE.Vector3(-0.88, 0.12, -0.58),
    new THREE.Vector3(0.88, 0.12, -0.58),
    new THREE.Vector3(0.88, 0.12, 0.58),
    new THREE.Vector3(-0.88, 0.12, 0.58),
    new THREE.Vector3(-0.88, 0.12, -0.58)
  ], 0x111111, 1);
  frame.visible = false;
  g.add(frame);

  panelAMinis.push({ kind, group: g, plate, inc, refl, trans, marks, frame });
  activeFrames[kind] = frame;
  return g;
}

makeMiniSurface('black', new THREE.Vector3(-1.35, 0, 0.75));
makeMiniSurface('white', new THREE.Vector3(1.35, 0, 0.75));
makeMiniSurface('yellowReflect', new THREE.Vector3(-1.35, 0, -0.95));
makeMiniSurface('yellowAbsorb', new THREE.Vector3(1.35, 0, -0.95));

const tinyLegend = new THREE.Group();
tinyLegend.position.set(-2.35, 0.02, -1.75);
tinyLegend.scale.setScalar(0.42);
tinyLegend.add(makeArrow(new THREE.Vector3(0, 0.12, 0), new THREE.Vector3(0.48, 0.12, 0), 0x222222, 0.01, 0.04, 0.09));
tinyLegend.add(makeAbsorbMark(new THREE.Vector3(0.70, 0.08, 0), 0x333333));
tinyLegend.add(makeArrow(new THREE.Vector3(0, -0.16, 0), new THREE.Vector3(0.48, -0.16, 0.24), 0x888888, 0.01, 0.04, 0.09, 0.55));
panelA.add(tinyLegend);

/* Panel (b): color wheel */
const wheelR = 1.35;
const wheelGroup = new THREE.Group();
panelB.add(wheelGroup);

const wheelMeshes = [];
const nWedges = 144;
for (let i = 0; i < nWedges; i++) {
  const deg0 = 150 + i * 360 / nWedges;
  const deg1 = 150 + (i + 1) * 360 / nWedges;
  const a0 = THREE.MathUtils.degToRad(deg0);
  const a1 = THREE.MathUtils.degToRad(deg1);
  const mid = (a0 + a1) / 2;
  const wl = angleToWl(mid);
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  for (let k = 0; k <= 4; k++) {
    const a = a0 + (a1 - a0) * (k / 4);
    shape.lineTo(Math.cos(a) * wheelR, Math.sin(a) * wheelR);
  }
  shape.lineTo(0, 0);
  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(shape), mat(wavelengthColor(wl), 0.98));
  mesh.userData.wl = wl;
  wheelGroup.add(mesh);
  wheelMeshes.push(mesh);
  registerInteractive(mesh, {
    title: `${wl} nm`,
    body: `Click to choose this absorbed wavelength. The opposite point on the wheel indicates the complementary color that remains visible.`,
    tooltip: `Select absorbed wavelength near ${wl} nm`,
    onClick: () => {
      state.wavelength = wl;
      document.getElementById('wavelength').value = wl;
      updateAll(false);
    }
  });
}

for (const a of wheelAnchors) {
  const ang = THREE.MathUtils.degToRad(a.deg);
  wheelGroup.add(lineObj([
    new THREE.Vector3(0, 0, 0.025),
    new THREE.Vector3(Math.cos(ang) * wheelR, Math.sin(ang) * wheelR, 0.025)
  ], 0x000000, 1));
}
const circlePts = [];
for (let i = 0; i <= 192; i++) {
  const a = i / 192 * Math.PI * 2;
  circlePts.push(new THREE.Vector3(Math.cos(a) * wheelR, Math.sin(a) * wheelR, 0.035));
}
wheelGroup.add(lineObj(circlePts, 0x000000, 1));

const selectedMarker = new THREE.Mesh(new THREE.SphereGeometry(0.06, 18, 12), mat(0xffffff, 1));
const compMarker = new THREE.Mesh(new THREE.SphereGeometry(0.055, 18, 12), mat(0xffffff, 1));
wheelGroup.add(selectedMarker, compMarker);
const selectedPointer = lineObj([new THREE.Vector3(), new THREE.Vector3(1, 0, 0)], 0x000000, 1);
const compPointer = lineObj([new THREE.Vector3(), new THREE.Vector3(-1, 0, 0)], 0x444444, 1);
const highlightArc = lineObj([new THREE.Vector3()], 0x000000, 1);
wheelGroup.add(selectedPointer, compPointer, highlightArc);

/* Panel (c): front-facing test tube and rays */
const tubeGroup = new THREE.Group();
panelC.add(tubeGroup);

const tubeGlass = new THREE.Mesh(new THREE.CapsuleGeometry(0.36, 2.52, 20, 44), mat(0xb7d9d9, 0.35));
tubeGlass.position.set(0, -0.12, 0.02);
tubeGroup.add(tubeGlass);

const outerRim = new THREE.Mesh(new THREE.TorusGeometry(0.39, 0.045, 10, 64), mat(0x88b6b6, 0.55));
outerRim.scale.y = 0.25;
outerRim.position.set(0, 1.32, 0.08);
tubeGroup.add(outerRim);

const innerRim = new THREE.Mesh(new THREE.TorusGeometry(0.27, 0.02, 8, 48), mat(0xe7ffff, 0.55));
innerRim.scale.y = 0.22;
innerRim.position.set(0, 1.35, 0.1);
tubeGroup.add(innerRim);

const liquidMat = mat(0x3f86ff, 0.75);
const liquidBody = new THREE.Mesh(new THREE.CylinderGeometry(0.29, 0.29, 2.08, 42), liquidMat);
liquidBody.position.set(0, -0.42, 0.09);
tubeGroup.add(liquidBody);
const liquidBottom = new THREE.Mesh(new THREE.SphereGeometry(0.29, 42, 18), liquidMat.clone());
liquidBottom.scale.y = 0.72;
liquidBottom.position.set(0, -1.46, 0.09);
tubeGroup.add(liquidBottom);
const liquidTop = new THREE.Mesh(new THREE.CircleGeometry(0.29, 48), liquidMat.clone());
liquidTop.scale.y = 0.22;
liquidTop.position.set(0, 0.62, 0.12);
tubeGroup.add(liquidTop);

tubeGroup.add(lineObj([new THREE.Vector3(-0.18, 1.13, 0.16), new THREE.Vector3(-0.18, -1.42, 0.16)], 0xffffff, 0.5));
tubeGroup.add(lineObj([new THREE.Vector3(0.18, 1.04, 0.16), new THREE.Vector3(0.18, -1.27, 0.16)], 0xffffff, 0.28));

const incomingC = [], outgoingC = [], absorbedC = [];
for (let i = 0; i < spectrum.length; i++) {
  const band = spectrum[i];
  const y = 0.78 - i * 0.27;
  const inc = makeArrow(new THREE.Vector3(-2.55, y, 0), new THREE.Vector3(-0.48, y, 0), band.color, 0.011, 0.055, 0.14, 1);
  panelC.add(inc);
  incomingC.push(inc);

  const out = makeArrow(new THREE.Vector3(0.56, y, 0), new THREE.Vector3(2.70, y, 0), band.color, 0.011, 0.055, 0.14, 1);
  panelC.add(out);
  outgoingC.push(out);

  const stop = makeArrow(new THREE.Vector3(-0.22, y, 0.02), new THREE.Vector3(0.18, y, 0.02), band.color, 0.011, 0.05, 0.12, 0.35);
  panelC.add(stop);
  absorbedC.push(stop);

  registerInteractive(inc, {
    title: `${band.name} band in white light`,
    body: `White light contains this ${band.name} wavelength band before entering the solution.`,
    tooltip: `${band.name} incoming band`
  });
  registerInteractive(out, {
    title: `${band.name} transmitted band`,
    body: `Bands not strongly absorbed by the solution pass through and combine to produce the apparent color.`,
    tooltip: `${band.name} transmitted band`
  });
}

registerInteractive(tubeGlass, {
  title: 'Selective absorption in solution',
  body: 'The blue solution absorbs orange-red light near 620 nm. The remaining transmitted wavelengths combine to look blue.',
  tooltip: 'Test tube: absorbed colors are removed'
});

/* Labels */
const labelData = [];
function addGroupLabel(group, text, localPos, options = {}) {
  const entry = addLabel(text, localToWorld(group, localPos[0], localPos[1], localPos[2] || 0), options);
  labelData.push({
    entry,
    group,
    localPos: new THREE.Vector3(localPos[0], localPos[1], localPos[2] || 0),
    visible: true
  });
  return entry;
}

function isAttached(obj) {
  let o = obj;
  while (o) {
    if (o === scene) return true;
    o = o.parent;
  }
  return false;
}

function refreshFigureLabels() {
  scene.updateMatrixWorld(true);
  for (const l of labelData) {
    if (!l.visible || !isAttached(l.group)) {
      l.entry.pos.set(9999, 9999, 9999);
    } else {
      l.group.updateMatrixWorld(true);
      l.entry.pos.copy(l.group.localToWorld(l.localPos.clone()));
    }
  }
}

const labelA = addGroupLabel(panelA, '(a)', [0, 0.12, -2.05], { fontSize: '18px' });
const legendText = addGroupLabel(panelA, 'absorbed   reflected/transmitted', [-1.72, 0.18, -1.78], { fontSize: '10px' });

const labelB = addGroupLabel(panelB, '(b)', [0, -1.78, 0], { fontSize: '18px' });
const wheelNote = addGroupLabel(panelB, '', [0, -1.55, 0], { fontSize: '12px', background: 'rgba(255,255,255,0.82)' });

for (const a of wheelAnchors) {
  const ang = THREE.MathUtils.degToRad(a.deg);
  let dx = 0, dy = 0;
  if (a.wl === 400) dy = -0.02;
  if (a.wl === 800) dy = 0.04;
  addGroupLabel(panelB, `${a.wl} nm`, [Math.cos(ang) * 1.58 + dx, Math.sin(ang) * 1.58 + dy, 0], { fontSize: '17px' });
}

const whiteLightLabel = addGroupLabel(panelC, 'White light', [-1.55, 1.02, 0], { fontSize: '17px' });
const outLightLabel = addGroupLabel(panelC, 'Blue-appearing light', [1.58, 1.02, 0], { fontSize: '17px' });
const labelC = addGroupLabel(panelC, '(c)', [0, -1.92, 0], { fontSize: '18px' });

/* Dynamic updates */
function updateSurfacePanel() {
  const selectedBand = nearestBand(state.wavelength).name;
  const typeToKind = {
    'Black absorbing': 'black',
    'White reflecting': 'white',
    'Transparent': 'white',
    'Colored': 'yellowAbsorb'
  };

  for (const mini of panelAMinis) {
    mini.frame.visible = mini.kind === typeToKind[state.surfaceType];

    for (let i = 0; i < spectrum.length; i++) {
      const band = spectrum[i];
      let reflect = false, transmit = false, absorb = false;

      if (mini.kind === 'black') {
        absorb = true;
      } else if (mini.kind === 'white') {
        reflect = true;
        transmit = state.surfaceType === 'Transparent';
      } else if (mini.kind === 'yellowReflect') {
        reflect = band.name === 'yellow';
        absorb = !reflect;
      } else if (mini.kind === 'yellowAbsorb') {
        const closeToSelected = band.name === selectedBand || Math.abs(band.wl - state.wavelength) <= 25;
        const yellowSurvive = band.name === 'yellow' || band.name === 'green' || band.name === 'orange' || band.name === 'red';
        absorb = closeToSelected || (!yellowSurvive && state.wavelength !== 430);
        reflect = !absorb;
      }

      if (mini.kind === 'white' && state.surfaceType === 'Transparent') {
        reflect = false;
        transmit = true;
      }

      setOpacity(mini.inc[i], band.name === selectedBand ? 1 : 0.92);
      setOpacity(mini.refl[i], reflect ? 0.96 : 0);
      setOpacity(mini.trans[i], transmit ? 0.55 : 0);
      setOpacity(mini.marks[i], absorb ? (band.name === selectedBand ? 1 : 0.42) : 0);
      mini.inc[i].scale.setScalar(band.name === selectedBand ? 1.13 : 1);
