function updateWheel() {
  const a = wlToAngle(state.wavelength);
  const ca = a + Math.PI;
  const selColor = wavelengthColor(state.wavelength);
  const compWl = complementaryWavelength(state.wavelength);
  const compColor = wavelengthColor(compWl);

  selectedMarker.position.set(Math.cos(a) * (wheelR + 0.075), Math.sin(a) * (wheelR + 0.075), 0.09);
  compMarker.position.set(Math.cos(ca) * (wheelR + 0.075), Math.sin(ca) * (wheelR + 0.075), 0.09);
  selectedMarker.material.color.set(selColor);
  compMarker.material.color.set(compColor);

  setLineGeometry(selectedPointer, [
    new THREE.Vector3(Math.cos(a) * 0.10, Math.sin(a) * 0.10, 0.065),
    new THREE.Vector3(Math.cos(a) * (wheelR + 0.20), Math.sin(a) * (wheelR + 0.20), 0.065)
  ]);
  setLineGeometry(compPointer, [
    new THREE.Vector3(Math.cos(ca) * 0.10, Math.sin(ca) * 0.10, 0.065),
    new THREE.Vector3(Math.cos(ca) * (wheelR + 0.17), Math.sin(ca) * (wheelR + 0.17), 0.065)
  ]);

  const arc = [];
  for (let k = -8; k <= 8; k++) {
    const aa = a + THREE.MathUtils.degToRad(k);
    arc.push(new THREE.Vector3(Math.cos(aa) * (wheelR + 0.035), Math.sin(aa) * (wheelR + 0.035), 0.08));
  }
  setLineGeometry(highlightArc, arc);

  wheelNote.div.innerHTML = `absorbed ${state.wavelength} nm ${colorName(state.wavelength)} → appears ${complementaryName(state.wavelength)}`;
}

function tubeAbsorptionFactor(band) {
  if (state.wavelength >= 600 && state.wavelength <= 660) {
    if (band.name === 'orange' || band.name === 'red') return 1;
    return 0;
  }
  const diff = Math.abs(band.wl - state.wavelength);
  if (diff <= 25) return 1;
  if (diff <= 55) return 0.55;
  return 0;
}

function updateTube() {
  const compWl = complementaryWavelength(state.wavelength);
  const liquidColor = state.wavelength >= 600 && state.wavelength <= 660 ? 0x3f86ff : wavelengthColor(compWl);
  liquidMat.color.set(liquidColor);
  liquidBottom.material.color.set(liquidColor);
  liquidTop.material.color.set(liquidColor);

  for (let i = 0; i < spectrum.length; i++) {
    const band = spectrum[i];
    const absorb = tubeAbsorptionFactor(band);
    setOpacity(incomingC[i], 1);
    setOpacity(outgoingC[i], Math.max(0, 1 - absorb));
    setOpacity(absorbedC[i], absorb > 0 ? 0.35 + 0.35 * absorb : 0);
  }

  const app = state.wavelength >= 600 && state.wavelength <= 660 ? 'Blue' : complementaryName(state.wavelength).replace(/^./, c => c.toUpperCase());
  outLightLabel.div.innerHTML = `${app}-appearing light`;
}

