// @FIGURE_CODE_BEGIN
// panel containers → THREE.Group for source-like linked overview and selectable isolated panels
// panel (a) four surface plates → PlaneGeometry rectangles in XZ plane arranged as textbook 2×2: black absorbing, white reflecting, yellow selective reflection, yellow complementary absorption
// panel (a) gray footprints → Line loops just below or behind each plate
// panel (a) incoming visible-spectrum arrows → CylinderGeometry shafts + ConeGeometry heads, seven parallel vivid arrows into each mini-plate
// panel (a) reflected arrows → matching arrows bending toward upper-right/back-right for reflecting bands
// panel (a) transmitted arrows → faint arrows continuing through the plate only for transparent selection
// panel (a) absorbed markers → small optional stop dots at impact points, hidden by default for source-faithful view
// panel (a) optional active frame and mini legend → Line objects, hidden unless teaching overlays are enabled
// panel (b) color wheel sectors → many ShapeGeometry wedge meshes in screen-facing plane, smoothly interpolated around wavelength anchors
// panel (b) wedge boundaries and outline → black Line radial boundaries plus outer circular Line
// panel (b) optional selected/complement markers and highlight arc → rim SphereGeometry and Line objects, hidden unless teaching overlays are enabled
// panel (c) glass test tube → transparent CapsuleGeometry body, TorusGeometry elliptical rim, pale outline/highlight Lines
// panel (c) blue liquid → transparent CylinderGeometry plus rounded SphereGeometry bottom and elliptical CircleGeometry top
// panel (c) light bundles → seven incoming arrows; outgoing arrows suppress orange/red for 620 nm absorption
// labels → addLabel for panel letters, wavelength labels, White light, and apparent transmitted-light label

const spectrum = [
  { name: 'violet', wl: 400, color: 0x4b00ff, css: '#4b00ff' },
  { name: 'blue', wl: 430, color: 0x1e3cff, css: '#1e3cff' },
  { name: 'cyan', wl: 490, color: 0x49e6e6, css: '#49e6e6' },
  { name: 'green', wl: 560, color: 0x33ff00, css: '#33ff00' },
  { name: 'yellow', wl: 580, color: 0xffe600, css: '#ffe600' },
  { name: 'orange', wl: 620, color: 0xff7a00, css: '#ff7a00' },
  { name: 'red', wl: 800, color: 0xff0000, css: '#ff0000' }
];

const wheelAnchors = [
  { wl: 800, deg: 150, color: 0xff0000 },
  { wl: 400, deg: 180, color: 0x4b00ff },
  { wl: 430, deg: 210, color: 0x1e3cff },
  { wl: 490, deg: 270, color: 0x49e6e6 },
  { wl: 560, deg: 330, color: 0x33ff00 },
  { wl: 580, deg: 390, color: 0xffe600 },
  { wl: 620, deg: 450, color: 0xff7a00 },
  { wl: 800, deg: 510, color: 0xff0000 }
];

const state = {
  panelView: 'Linked overview',
  wavelength: 620,
  surfaceType: 'Colored',
  overlays: false,
  step: 4
};

const root = new THREE.Group();
scene.add(root);

const panelA = new THREE.Group();
const panelB = new THREE.Group();
const panelC = new THREE.Group();

const screenRight = new THREE.Vector3(Math.SQRT1_2, 0, -Math.SQRT1_2);
const screenUp = new THREE.Vector3(-0.408248290463863, 0.816496580927726, -0.408248290463863);
const screenNormal = new THREE.Vector3(0.577350269189626, 0.577350269189626, 0.577350269189626);
const faceMatrix = new THREE.Matrix4().makeBasis(screenRight, screenUp, screenNormal);
panelB.setRotationFromMatrix(faceMatrix);
panelC.setRotationFromMatrix(faceMatrix);

function mat(color, opacity = 1, side = THREE.DoubleSide) {
  return new THREE.MeshBasicMaterial({
    color,
    side,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 0.82,
    toneMapped: false
  });
}

function lineObj(points, color = 0x000000, opacity = 1) {
  return new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(points),
    new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity, toneMapped: false })
  );
}

function orientBetween(obj, start, end) {
  const dir = end.clone().sub(start);
  obj.position.copy(start).add(end).multiplyScalar(0.5);
  obj.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
}

function makeArrow(start, end, color, radius = 0.014, headRadius = 0.065, headLength = 0.18, opacity = 1) {
  const g = new THREE.Group();
  const s = start.clone();
  const e = end.clone();
  const dir = e.clone().sub(s);
  const len = Math.max(dir.length(), 0.001);
  const shaftLen = Math.max(0.01, len - headLength);
  const shaftEnd = s.clone().add(dir.clone().multiplyScalar(shaftLen / len));
  const m = mat(color, opacity, THREE.FrontSide);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, shaftLen, 12), m);
  orientBetween(shaft, s, shaftEnd);
  const head = new THREE.Mesh(new THREE.ConeGeometry(headRadius, headLength, 18), m.clone());
  orientBetween(head, shaftEnd, e);
  g.add(shaft, head);
  return g;
}

function setOpacity(obj, opacity) {
  obj.visible = opacity > 0.01;
  obj.traverse(o => {
    if (o.material) {
      o.material.transparent = opacity < 1;
      o.material.opacity = opacity;
      o.material.depthWrite = opacity >= 0.82;
    }
  });
}

function setLineGeometry(line, pts) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
}

function normalizeWheelDeg(deg) {
  while (deg < 150) deg += 360;
  while (deg > 510) deg -= 360;
  return deg;
}

function wlToAngle(wl) {
  const w = Math.max(400, Math.min(800, wl));
  for (let i = 0; i < wheelAnchors.length - 1; i++) {
    const a = wheelAnchors[i], b = wheelAnchors[i + 1];
    if (w >= Math.min(a.wl, b.wl) && w <= Math.max(a.wl, b.wl)) {
      if ((a.wl === 800 && b.wl === 400) || (a.wl < b.wl)) {
        const t = (w - a.wl) / (b.wl - a.wl);
        if (t >= -1e-6 && t <= 1 + 1e-6) return THREE.MathUtils.degToRad(a.deg + t * (b.deg - a.deg));
      }
    }
  }
  const ordered = wheelAnchors.slice(1);
  for (let i = 0; i < ordered.length - 1; i++) {
    const a = ordered[i], b = ordered[i + 1];
    if (w >= a.wl && w <= b.wl) {
      const t = (w - a.wl) / (b.wl - a.wl);
      return THREE.MathUtils.degToRad(a.deg + t * (b.deg - a.deg));
    }
  }
  return THREE.MathUtils.degToRad(450);
}

function angleToWl(rad) {
  const deg = normalizeWheelDeg(THREE.MathUtils.radToDeg(rad));
  for (let i = 0; i < wheelAnchors.length - 1; i++) {
    const a = wheelAnchors[i], b = wheelAnchors[i + 1];
    if (deg >= a.deg && deg <= b.deg) {
      const t = (deg - a.deg) / (b.deg - a.deg);
      return Math.round((a.wl + t * (b.wl - a.wl)) / 10) * 10;
    }
  }
  return 620;
}

function interpolateHex(c0, c1, t) {
  const a = new THREE.Color(c0);
  const b = new THREE.Color(c1);
  return a.lerp(b, t).getHex();
}

function angleColor(rad) {
  const deg = normalizeWheelDeg(THREE.MathUtils.radToDeg(rad));
  for (let i = 0; i < wheelAnchors.length - 1; i++) {
    const a = wheelAnchors[i], b = wheelAnchors[i + 1];
    if (deg >= a.deg && deg <= b.deg) {
      const t = (deg - a.deg) / (b.deg - a.deg);
      return interpolateHex(a.color, b.color, t);
    }
  }
  return 0xff7a00;
}

function nearestBand(wl) {
  let best = spectrum[0];
  for (const s of spectrum) {
    if (Math.abs(s.wl - wl) < Math.abs(best.wl - wl)) best = s;
  }
  return best;
}

function wavelengthColor(wl) {
  return angleColor(wlToAngle(wl));
}

function colorName(wl) {
  return nearestBand(wl).name;
}

function complementaryWavelength(wl) {
  return angleToWl(wlToAngle(wl) + Math.PI);
}

function complementaryName(wl) {
  return colorName(complementaryWavelength(wl));
}

function localToWorld(group, x, y, z = 0) {
  group.updateMatrixWorld(true);
  return group.localToWorld(new THREE.Vector3(x, y, z));
}

/* Panel (a): four textbook surface cases */
const panelAMinis = [];
const overlayObjects = [];

function plateFootprint(w = 1.55, h = 0.95, y = -0.018) {
  return lineObj([
    new THREE.Vector3(-w / 2, y, -h / 2),
    new THREE.Vector3(w / 2, y, -h / 2),
    new THREE.Vector3(w / 2, y, h / 2),
    new THREE.Vector3(-w / 2, y, h / 2),
    new THREE.Vector3(-w / 2, y, -h / 2)
  ], 0x808080, 1);
}

function makeStopDot(pos, color) {
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.045, 16, 10), mat(color, 0.92));
  dot.position.copy(pos).add(new THREE.Vector3(0, 0.045, 0));
  return dot;
}

function makeMiniSurface(kind, pos) {
  const g = new THREE.Group();
  g.position.copy(pos);
  panelA.add(g);

  let pColor = 0xffff66, pOpacity = 0.92;
  if (kind === 'black') { pColor = 0x000000; pOpacity = 1; }
  if (kind === 'white') { pColor = 0xf5f5f5; pOpacity = 0.22; }
  if (kind === 'yellowReflect') { pColor = 0xffff66; pOpacity = 0.86; }
  if (kind === 'yellowAbsorb') { pColor = 0xffff66; pOpacity = 0.86; }

  const plate = new THREE.Mesh(new THREE.PlaneGeometry(1.55, 0.95), mat(pColor, pOpacity));
  plate.rotation.x = -Math.PI / 2;
  g.add(plate);
  const footprint = plateFootprint();
  g.add(footprint);

  const inc = [], refl = [], trans = [], stops = [];
  for (let i = 0; i < spectrum.length; i++) {
    const band = spectrum[i];
    const z = 0.39 - i * 0.12;
    const hit = new THREE.Vector3(-0.33 + i * 0.035, 0.045, z);
    const start = hit.clone().add(new THREE.Vector3(-0.95, 0.58, -0.46));
    const incoming = makeArrow(start, hit, band.color, 0.0095, 0.046, 0.125, 1);
    g.add(incoming);
    inc.push(incoming);

    const out = makeArrow(
      hit.clone().add(new THREE.Vector3(0.025, 0.03, 0.012)),
      hit.clone().add(new THREE.Vector3(0.96, 0.48, 0.48)),
      band.color, 0.0095, 0.046, 0.125, 0.96
    );
    g.add(out);
    refl.push(out);

    const through = makeArrow(
      hit.clone().add(new THREE.Vector3(0.025, -0.012, 0.012)),
      hit.clone().add(new THREE.Vector3(0.95, -0.18, 0.43)),
      band.color, 0.008, 0.038, 0.105, 0.45
    );
    g.add(through);
    trans.push(through);

    const stop = makeStopDot(hit, band.color);
    g.add(stop);
    stops.push(stop);
    overlayObjects.push(stop);

    registerInteractive(incoming, {
      title: `${band.name} incoming light`,
      body: `This ${band.name} band is one component of the visible spectrum striking the surface.`,
      tooltip: `${band.name} incoming band`
    });
    registerInteractive(out, {
      title: `${band.name} reflected light`,
      body: `A reflected band leaves the surface and can contribute to the observed color.`,
      tooltip: `${band.name} reflected band`
    });
  }

  const frame = lineObj([
    new THREE.Vector3(-0.88, 0.12, -0.58),
    new THREE.Vector3(0.88, 0.12, -0.58),
    new THREE.Vector3(0.88, 0.12, 0.58),
    new THREE.Vector3(-0.88, 0.12, 0.58),
    new THREE.Vector3(-0.88, 0.12, -0.58)
  ], 0x111111, 1);
  frame.visible = false;
  g.add(frame);
  overlayObjects.push(frame);

  panelAMinis.push({ kind, group: g, plate, footprint, inc, refl, trans, stops, frame });
  return g;
}

