/* Panel (b): complementary color wheel */
const wheelR = 1.35;
const wheelGroup = new THREE.Group();
panelB.add(wheelGroup);

const nWedges = 216;
for (let i = 0; i < nWedges; i++) {
  const deg0 = 150 + i * 360 / nWedges;
  const deg1 = 150 + (i + 1) * 360 / nWedges;
  const a0 = THREE.MathUtils.degToRad(deg0);
  const a1 = THREE.MathUtils.degToRad(deg1);
  const mid = (a0 + a1) / 2;
  const wl = angleToWl(mid);
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  for (let k = 0; k <= 5; k++) {
    const a = a0 + (a1 - a0) * (k / 5);
    shape.lineTo(Math.cos(a) * wheelR, Math.sin(a) * wheelR);
  }
  shape.lineTo(0, 0);
  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(shape), mat(angleColor(mid), 0.99));
  mesh.userData.wl = wl;
  wheelGroup.add(mesh);
  registerInteractive(mesh, {
    title: `${wl} nm sector`,
    body: `Clicking this sector selects an absorbed wavelength near ${wl} nm. The color diametrically opposite on the wheel is the complementary color that remains visible.`,
    tooltip: `Click: absorbed wavelength near ${wl} nm`,
    onClick: () => {
      state.wavelength = wl;
      document.getElementById('wavelength').value = wl;
      updateAll(false);
    }
  });
}

