/* Labels */
const labelData = [];
function addGroupLabel(group, text, localPos, options = {}) {
  const entry = addLabel(text, localToWorld(group, localPos[0], localPos[1], localPos[2] || 0), options);
  labelData.push({
    entry,
    group,
    localPos: new THREE.Vector3(localPos[0], localPos[1], localPos[2] || 0),
    visible: true
  });
  return entry;
}

function isAttached(obj) {
  let o = obj;
  while (o) {
    if (o === scene) return true;
    o = o.parent;
  }
  return false;
}

function refreshFigureLabels() {
  scene.updateMatrixWorld(true);
  for (const l of labelData) {
    if (!l.visible || !isAttached(l.group)) {
      l.entry.pos.set(9999, 9999, 9999);
    } else {
      l.group.updateMatrixWorld(true);
      l.entry.pos.copy(l.group.localToWorld(l.localPos.clone()));
    }
  }
}

