/* Dynamic updates */
function updateOverlayVisibility() {
  const show = state.overlays;
  for (const o of overlayObjects) o.visible = show;
  tinyLegend.visible = show && state.panelView === 'Surface interactions (a)';
  wheelNote.div.style.display = show && isAttached(panelB) ? '' : 'none';
}

function updateSurfacePanel() {
  const selectedBand = nearestBand(state.wavelength).name;
  const typeToKind = {
    'Black absorbing': 'black',
    'White reflecting': 'white',
    'Transparent': 'white',
    'Colored': 'yellowAbsorb'
  };

  for (const mini of panelAMinis) {
    mini.frame.visible = state.overlays && mini.kind === typeToKind[state.surfaceType];

    if (mini.kind === 'white' && state.surfaceType === 'Transparent') {
      mini.plate.material.color.set(0xf5f5f5);
      mini.plate.material.opacity = 0.25;
      mini.plate.material.transparent = true;
    } else if (mini.kind === 'white') {
      mini.plate.material.color.set(0xf5f5f5);
      mini.plate.material.opacity = 0.22;
      mini.plate.material.transparent = true;
    }

    for (let i = 0; i < spectrum.length; i++) {
      const band = spectrum[i];
      let reflect = false, transmit = false, absorb = false;

      if (mini.kind === 'black') {
        absorb = true;
      } else if (mini.kind === 'white') {
        reflect = state.surfaceType !== 'Transparent';
        transmit = state.surfaceType === 'Transparent';
      } else if (mini.kind === 'yellowReflect') {
        reflect = band.name === 'yellow';
        absorb = !reflect;
      } else if (mini.kind === 'yellowAbsorb') {
        const complementaryAbsorb = band.name === selectedBand || Math.abs(band.wl - state.wavelength) <= 25;
        const yellowSurvive = band.name === 'yellow' || band.name === 'green' || band.name === 'orange';
        absorb = complementaryAbsorb || (!yellowSurvive && state.wavelength !== 430);
        reflect = !absorb;
      }

      const isSelected = band.name === selectedBand;
      setOpacity(mini.inc[i], isSelected ? 1 : 0.94);
      setOpacity(mini.refl[i], reflect ? 0.96 : 0);
      setOpacity(mini.trans[i], transmit ? 0.55 : 0);
      setOpacity(mini.stops[i], state.overlays && absorb ? (isSelected ? 1 : 0.45) : 0);
      mini.inc[i].scale.setScalar(isSelected && state.overlays ? 1.10 : 1);
    }
  }
}

function updateWheel() {
  const a = wlToAngle(state.wavelength);
  const ca = a + Math.PI;
  const selColor = wavelengthColor(state.wavelength);
  const compWl = complementaryWavelength(state.wavelength);
  const compColor = wavelengthColor(compWl);

  selectedMarker.position.set(Math.cos(a) * (wheelR + 0.07), Math.sin(a) * (wheelR + 0.07), 0.09);
  compMarker.position.set(Math.cos(ca) * (wheelR + 0.07), Math.sin(ca) * (wheelR + 0.07), 0.09);
  selectedMarker.material.color.set(selColor);
  compMarker.material.color.set(compColor);

  setLineGeometry(selectedPointer, [
    new THREE.Vector3(0, 0, 0.065),
    new THREE.Vector3(Math.cos(a) * (wheelR + 0.16), Math.sin(a) * (wheelR + 0.16), 0.065)
  ]);
  setLineGeometry(compPointer, [
    new THREE.Vector3(0, 0, 0.065),
    new THREE.Vector3(Math.cos(ca) * (wheelR + 0.14), Math.sin(ca) * (wheelR + 0.14), 0.065)
  ]);

  const arc = [];
  for (let k = -7; k <= 7; k++) {
    const aa = a + THREE.MathUtils.degToRad(k);
    arc.push(new THREE.Vector3(Math.cos(aa) * (wheelR + 0.035), Math.sin(aa) * (wheelR + 0.035), 0.08));
  }
  setLineGeometry(highlightArc, arc);

  wheelNote.div.innerHTML = `absorbed ${state.wavelength} nm ${colorName(state.wavelength)} → appears ${complementaryName(state.wavelength)}`;
}

function tubeAbsorptionFactor(band) {
  if (state.wavelength >= 600 && state.wavelength <= 660) {
    if (band.name === 'orange' || band.name === 'red') return 1;
    return 0;
  }
  const diff = Math.abs(band.wl - state.wavelength);
  if (diff <= 25) return 1;
  if (diff <= 55) return 0.55;
  return 0;
}

function updateTube() {
  const compWl = complementaryWavelength(state.wavelength);
  const liquidColor = state.wavelength >= 600 && state.wavelength <= 660 ? 0x3f86ff : wavelengthColor(compWl);
  liquidMat.color.set(liquidColor);
  liquidBottom.material.color.set(liquidColor);
  liquidTop.material.color.set(liquidColor);

  for (let i = 0; i < spectrum.length; i++) {
    const band = spectrum[i];
    const absorb = tubeAbsorptionFactor(band);
    setOpacity(incomingC[i], 1);
    setOpacity(outgoingC[i], Math.max(0, 1 - absorb));
    setOpacity(absorbedC[i], absorb > 0 ? 0.32 + 0.35 * absorb : 0);
  }

  const app = state.wavelength >= 600 && state.wavelength <= 660 ? 'Blue' : complementaryName(state.wavelength).replace(/^./, c => c.toUpperCase());
  outLightLabel.div.innerHTML = `${app}-appearing light`;
}

function updateReadouts() {
  document.getElementById('wavelengthReadout').textContent = `${state.wavelength} nm`;
}

function addOnly(...groups) {
  root.clear();
  for (const g of groups) root.add(g);
}

function applyLayout(refit = true) {
  panelA.position.set(0, 0, 0);
  panelB.position.set(0, 0, 0);
  panelC.position.set(0, 0, 0);
  panelA.scale.setScalar(1);
  panelB.scale.setScalar(1);
  panelC.scale.setScalar(1);

  if (state.panelView === 'Surface interactions (a)') {
    addOnly(panelA);
  } else if (state.panelView === 'Color wheel (b)') {
    addOnly(panelB);
  } else if (state.panelView === 'Test tube (c)') {
    addOnly(panelC);
  } else {
    addOnly(panelA, panelB, panelC);
    panelA.position.set(-1.44, 0.16, 0.36);
    panelA.scale.setScalar(0.50);
    panelB.position.set(1.70, 1.03, 0.18);
    panelB.scale.setScalar(0.54);
    panelC.position.set(0.14, -1.26, 0.0);
    panelC.scale.setScalar(0.55);
  }

  updateOverlayVisibility();
  refreshFigureLabels();
  if (refit) {
    setCameraView({
      projection: 'orthographic',
      axisScreenAngles: { x: 30, z: 30 },
      rollDeg: 0,
      heightFraction: state.panelView === 'Linked overview' ? 0.82 : 0.72
    });
    refreshFigureLabels();
  }
}

function updateAll(refit = true) {
  updateReadouts();
  updateSurfacePanel();
  updateWheel();
  updateTube();
  applyLayout(refit);
}

const demoSteps = [
  {
    title: 'Absorption on the wheel',
    narration: 'Start on the color wheel with absorption near 620 nm, in the orange-red region. The marker opposite it indicates the complementary blue/cyan appearance.',
    state: { panelView: 'Color wheel (b)', wavelength: 620, surfaceType: 'Colored' }
  },
  {
    title: 'Colored surface',
    narration: 'Switch to the surface panel. For a colored yellow-appearing surface, most colors are absorbed while yellow-related light is reflected toward the viewer.',
    state: { panelView: 'Surface interactions (a)', wavelength: 430, surfaceType: 'Colored' }
  },
  {
    title: 'Black, white, and transparent limits',
    narration: 'Changing the surface type shows the limiting cases: black absorbs all visible bands, white reflects them all, and a transparent material transmits them through the plate.',
    state: { panelView: 'Surface interactions (a)', wavelength: 560, surfaceType: 'White reflecting' }
  },
  {
    title: 'Blue-appearing solution',
    narration: 'In the test tube, orange-red absorption removes those wavelengths from white light. The transmitted mixture is dominated by shorter wavelengths and appears blue.',
    state: { panelView: 'Test tube (c)', wavelength: 620, surfaceType: 'Colored' }
  },
  {
    title: 'Linked comparison',
    narration: 'The overview shows the same selected wavelength driving all panels together: highlighted sector on the wheel, absorption/reflection on the surface, and transmitted color through the solution.',
    state: { panelView: 'Linked overview', wavelength: 620, surfaceType: 'Colored' }
  }
];

function goToStep(i) {
  state.step = (i + demoSteps.length) % demoSteps.length;
  const step = demoSteps[state.step];
  Object.assign(state, step.state);
  document.getElementById('panelView').value = state.panelView;
  document.getElementById('wavelength').value = state.wavelength;
  document.getElementById('surfaceType').value = state.surfaceType;
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarration').textContent = step.narration;
  updateAll(true);
}
window.goToStep = goToStep;

document.getElementById('panelView').addEventListener('change', e => {
  state.panelView = e.target.value;
  updateAll(true);
});
document.getElementById('wavelength').addEventListener('input', e => {
  state.wavelength = Number(e.target.value);
  updateAll(false);
});
document.getElementById('surfaceType').addEventListener('change', e => {
  state.surfaceType = e.target.value;
  updateAll(false);
});
document.getElementById('teachingOverlays').addEventListener('change', e => {
  state.overlays = e.target.checked;
  updateAll(false);
});
document.getElementById('prevStep').addEventListener('click', () => goToStep(state.step - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(state.step + 1));

updateAll(true);
// @FIGURE_CODE_END

